// BELEG_Fehlerbilder: je Fehlerbild ein echtes Beispiel aus den Quelldaten, vorher (Rohwert) und nachher (harmonisiert).
// Die Beispiele kommen aus dem Fehlerprotokoll des Datengenerators (fehler_log.csv); gewählt wird der Datensatz mit den wenigsten weiteren Fehlern.
// Bei Fehlern, die nicht automatisch behoben werden, steht unter Nachher der Befund der Prüfliste.
let
    t = (v) => if v = null then "(leer)" else if v is text then (if Text.Trim(v) = "" then "(leer)" else v) else if v is logical then (if v then "ja" else "nein") else if v is date then Date.ToText(v, "dd.MM.yyyy") else Text.From(v, "de-DE"),
    kvs = (r as record, namen as list) as text => Text.Combine(List.Transform(namen, (n) => n & ": " & t(Record.FieldOrDefault(r, n, null))), " | "),
    kvx = (r as record, namen as list) as text => Text.Combine(List.Transform(List.Select(namen, (n) => Record.FieldOrDefault(r, n, null) <> null), (n) => n & ": " & t(Record.Field(r, n))), " | "),
    bf = (h as record, w as text) as text => let l = List.Select(Text.Split(h[Befunde] ?? "", "; "), each Text.Contains(_, w)) in if List.IsEmpty(l) then "kein Befund" else "Prüfliste: " & l{0},
    geld = (x) => Number.ToText(x, "#,##0.00", "de-DE"),
    rec = (T as table, col as text, id as text) as nullable record => List.First(Table.ToRecords(Table.SelectRows(T, each Text.From(Record.Field(_, col)) = id)), null),
    // Rohdaten ohne jede Typumwandlung
    ER = Table.Buffer(Table.PromoteHeaders(Csv.Document(File.Contents(pPfad & "quellen\erp\KUNDE.txt"), [Delimiter = ";", Columns = 17, Encoding = 1252, QuoteStyle = QuoteStyle.Csv]), [PromoteAllScalars = true])),
    SR = Table.Buffer(Table.PromoteHeaders(Csv.Document(File.Contents(pPfad & "quellen\shop\customers.csv"), [Delimiter = ",", Columns = 13, Encoding = 65001, QuoteStyle = QuoteStyle.Csv]), [PromoteAllScalars = true])),
    CR = Table.Buffer(Table.PromoteHeaders(Excel.Workbook(File.Contents(pPfad & "quellen\crm\CRM_Export.xlsx"), null, true){[Item = "Accounts", Kind = "Sheet"]}[Data], [PromoteAllScalars = true])),
    EH = Table.Buffer(KUNDE_h), SH = Table.Buffer(SHOP_h), CH = Table.Buffer(CRM_h),
    ALLH = Table.Buffer(Table.Combine({Table.SelectColumns(EH, {"Quelle", "Firma", "Name_norm", "Matchkey"}), Table.SelectColumns(SH, {"Quelle", "Firma", "Name_norm", "Matchkey"}), Table.SelectColumns(CH, {"Quelle", "Firma", "Name_norm", "Matchkey"})})),
    RT = (q as text) => if q = "ERP" then ER else if q = "Shop" then SR else CR,
    RI = (q as text) => if q = "ERP" then "KdNr" else if q = "Shop" then "customer_id" else "AccountId",
    HT = (q as text) => if q = "ERP" then EH else if q = "Shop" then SH else CH,
    HI = (q as text) => if q = "ERP" then "KdNr" else if q = "Shop" then "ShopID" else "AccountId",
    Log0 = Table.Buffer(Table.TransformColumnTypes(Table.PromoteHeaders(Csv.Document(File.Contents(pPfad & "sollwerte\fehler_log.csv"), [Delimiter = ";", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]), [PromoteAllScalars = true]), {{"Quelle", type text}, {"Tabelle", type text}, {"ID", type text}, {"Fehlertyp", type text}})),
    Log = Table.Buffer(Table.AddColumn(Log0, "n", (r) => Table.RowCount(Table.SelectRows(Log0, each [Quelle] = r[Quelle] and [ID] = r[ID])), Int64.Type)),
    ids = (q as text, f as text, n as number) as list => List.FirstN(Table.Sort(Table.SelectRows(Log, each [Quelle] = q and Text.StartsWith([Fehlertyp], f)), {{"n", Order.Ascending}, {"ID", Order.Ascending}})[ID], n),
    partner = (T as table, idcol as text, h as record) as table => Table.SelectRows(T, each [Matchkey] <> null and [Matchkey] = h[Matchkey] and [Name_norm] = h[Name_norm] and Record.Field(_, idcol) <> Record.Field(h, idcol)),
    varianten = (T as table, idcol as text, col as text, normal as list, k as number) as list =>
        let v = List.FirstN(List.Distinct(List.Select(Table.Column(T, col), each _ <> null and Text.Trim(Text.From(_)) <> "" and not List.Contains(normal, _))), k)
        in List.Transform(v, (x) => Text.From(Record.Field(Table.SelectRows(T, (z) => Record.Field(z, col) = x){0}, idcol))),
    G1 = "1 Zeichen und Format", G2 = "2 Kodierung", G3 = "3 Adresse", G4 = "4 Kontaktdaten", G5 = "5 Feldmissbrauch", G6 = "6 Datensätze und Schlüssel", G7 = "7 Bewegungsdaten",
    cA = "automatisch", cAP = "automatisch + Prüfliste", cP = "Prüfliste (manuell)", cK = "automatisch (Kaskade)",
    Sp = {
        [G = G1, B = "Zeichensatzfehler (Mojibake)", Q = "CRM", F = "Mojibake", V = (r) => kvx(r, {"Firma", "Nachname"}), N = (h, r) => kvx(h, {"Firma", "Nachname"}), R = "fnClean: Ersetzungsliste für doppelt kodierte Umlaute", A = cA],
        [G = G1, B = "Doppelte Leerzeichen (· = Leerzeichen)", Q = "ERP", F = "", W = List.FirstN(Table.SelectRows(ER, each Text.Contains([Firma], "  "))[KdNr], 1), V = (r) => "Firma: " & Text.Replace(r[Firma], " ", "·"), N = (h, r) => "Firma: " & Text.Replace(h[Firma], " ", "·"), R = "fnClean: Steuerzeichen, geschützte und doppelte Leerzeichen", A = cA],
        [G = G1, B = "Platzhalter statt leer", Q = "ERP", F = "Platzhalter", V = (r) => kvs(r, {"Vorname"}), N = (h, r) => kvs(h, {"Vorname"}), R = "fnClean: -, ?, k.A., xxx, n/a, unbekannt werden leer", A = cA],
        [G = G1, B = "Platzhalter statt leer", Q = "CRM", F = "Platzhalter", V = (r) => kvs(r, {"Anrede"}), N = (h, r) => kvs(h, {"Anrede"}), R = "fnClean: -, ?, k.A., xxx, n/a, unbekannt werden leer", A = cA],
        [G = G1, B = "Groß-/Kleinschreibung", Q = "Shop", F = "", W = List.FirstN(Table.SelectRows(SR, each Text.Length([last_name]) > 2 and [last_name] = Text.Upper([last_name]))[customer_id], 1), V = (r) => kvs(r, {"last_name"}), N = (h, r) => "Nachname: " & t(h[Nachname]) & " | für den Abgleich: " & t(fnNormName(h[Nachname])), R = "fnNormName: Abgleich ohne Groß-/Kleinschreibung; Anzeige bleibt", A = "automatisch (nur Abgleich)"],
        [G = G1, B = "PLZ als Zahl, führende Null fehlt", Q = "CRM", F = "PLZ als Zahl (Excel-Artefakt, führende", V = (r) => "PLZ: " & t(r[PLZ]) & (if r[PLZ] is number then " (Zahl)" else " (Text)") & " | Land: " & t(r[Land]), N = (h, r) => kvs(h, {"PLZ_norm", "LandISO"}), R = "Typ Text; DE, vierstellig und Zahl: führende 0 ergänzen", A = cA],
        [G = G1, B = "PLZ als Zahl", Q = "CRM", F = "PLZ als Zahl (Excel-Artefakt)", V = (r) => "PLZ: " & t(r[PLZ]) & (if r[PLZ] is number then " (Zahl)" else " (Text)"), N = (h, r) => "PLZ_norm: " & t(h[PLZ_norm]) & " (Text)", R = "Typ Text erzwingen", A = cA],
        [G = G1, B = "Datum nur monatsgenau", Q = "CRM", F = "Datum ungenau", V = (r) => kvs(r, {"Erstkontakt"}), N = (h, r) => kvs(h, {"Erstkontakt"}) & " | " & bf(h, "monatsgenau"), R = "Gebietsschema en-US; MM/YYYY wird Monatserster mit Kennzeichen", A = cAP],
        [G = G1, B = "Zeitzone (UTC)", Q = "Shop", F = "", W = List.FirstN(Table.SelectRows(SR, each Text.Contains([created_at], "T23:"))[customer_id], 1), V = (r) => kvs(r, {"created_at"}), N = (h, r) => kvs(h, {"Anlagedatum"}), R = "UTC nach MEZ umrechnen, dann erst das Datum bilden", A = cA],
        [G = G1, B = "Zahl als Text", Q = "ERP", F = "Zahlungsziel als Text", V = (r) => kvs(r, {"Zahlungsziel"}), N = (h, r) => kvs(h, {"Zahlungsziel"}), R = "nur die Ziffern übernehmen; -1 wird leer", A = cA],
        [G = G2, B = "J/N-Feld mit Fremdwert", Q = "ERP", F = "", W = varianten(ER, "KdNr", "Newsletter", {"J", "N"}, 2), V = (r) => kvs(r, {"Newsletter"}), N = (h, r) => kvs(h, {"Newsletter"}), R = "fnJN: j, ja, x, 1, true = ja; Unbekanntes bleibt leer", A = cA],
        [G = G2, B = "Land in Varianten", Q = "ERP", F = "", W = varianten(ER, "KdNr", "Land", {"D", "A", "CH"}, 3), V = (r) => kvs(r, {"Land"}), N = (h, r) => kvs(h, {"LandISO"}), R = "mapLand: Mapping-Tabelle auf ISO-Code", A = cA],
        [G = G2, B = "Land in Varianten", Q = "CRM", F = "", W = varianten(CR, "AccountId", "Land", {"Deutschland", "Österreich", "Schweiz"}, 3), V = (r) => kvs(r, {"Land"}), N = (h, r) => kvs(h, {"LandISO"}), R = "mapLand: Mapping-Tabelle auf ISO-Code", A = cA],
        [G = G2, B = "Land fehlt", Q = "CRM", F = "Land fehlt", n = 2, V = (r) => kvs(r, {"Land", "PLZ"}), N = (h, r) => kvs(h, {"LandISO"}) & (if h[LandISO] = null then " | " & bf(h, "Land") else ""), R = "fünfstellige PLZ gibt es in DACH nur in DE; vierstellig bleibt offen", A = "automatisch, Rest Prüfliste"],
        [G = G3, B = "PLZ im Ortsfeld", Q = "ERP", F = "PLZ im Ortsfeld", V = (r) => kvs(r, {"PLZ", "Ort"}), N = (h, r) => kvs(h, {"PLZ_norm", "Ort"}), R = "Ort beginnt mit Ziffer und PLZ ist leer: am ersten Leerzeichen trennen", A = cA],
        [G = G3, B = "PLZ mit Länderpräfix", Q = "ERP", F = "PLZ mit Länderpräfix", V = (r) => kvs(r, {"PLZ", "Land"}), N = (h, r) => kvs(h, {"PLZ_norm", "LandISO"}), R = "Präfix abtrennen; es stützt das Land, falls dieses fehlt", A = cA],
        [G = G3, B = "PLZ mit Länderpräfix", Q = "CRM", F = "PLZ mit Länderpräfix", V = (r) => kvs(r, {"PLZ", "Land"}), N = (h, r) => kvs(h, {"PLZ_norm", "LandISO"}), R = "Präfix abtrennen; es stützt das Land, falls dieses fehlt", A = cA],
        [G = G3, B = "PLZ ungültig", Q = "ERP", F = "PLZ ungültig", V = (r) => kvs(r, {"PLZ", "Land"}), N = (h, r) => kvs(h, {"Matchkey"}) & " | " & bf(h, "PLZ"), R = "Prüfung auf Ziffern und Länge je Land; kein Adressschlüssel", A = cP],
        [G = G3, B = "PLZ fehlt", Q = "CRM", F = "PLZ fehlt", V = (r) => kvs(r, {"PLZ", "Ort"}), N = (h, r) => kvs(h, {"Matchkey"}) & " | " & bf(h, "PLZ"), R = "nicht aus dem Ort geraten; kein Adressschlüssel", A = cP],
        [G = G3, B = "PLZ passt nicht zum Land", Q = "CRM", F = "PLZ passt nicht", V = (r) => kvs(r, {"PLZ", "Land"}), N = (h, r) => kvs(h, {"Matchkey"}) & " | " & bf(h, "PLZ passt"), R = "Länge der PLZ gegen das Land prüfen; kein Adressschlüssel", A = cP],
        [G = G3, B = "Hausnummer vor der Straße", Q = "ERP", F = "Hausnummer vor", V = (r) => kvs(r, {"Strasse"}), N = (h, r) => kvs(h, {"Strasse", "Hausnr"}), R = "fnStrasse: beginnt mit Ziffer, danach Text: umstellen", A = cA],
        [G = G3, B = "Hausnummer als Bereich", Q = "ERP", F = "Hausnummer-Bereich", n = 3, V = (r) => kvs(r, {"Strasse"}), N = (h, r) => kvs(h, {"Strasse", "Hausnr", "Matchkey"}), R = "Bereich bleibt im Feld; der Adressschlüssel nimmt die erste Nummer", A = cA],
        [G = G3, B = "Postfach im Straßenfeld", Q = "ERP", F = "Postfach", V = (r) => kvs(r, {"Strasse"}), N = (h, r) => kvs(h, {"Matchkey"}) & " | " & bf(h, "Postfach"), R = "Postfach ist keine Lieferadresse: kein Adressschlüssel", A = cP],
        [G = G3, B = "Straße und Hausnummer vertauscht", Q = "CRM", F = "Felder vertauscht", V = (r) => kvs(r, {"Strasse", "Hausnr"}), N = (h, r) => kvs(h, {"Strasse", "Hausnr"}), R = "Straße beginnt mit Ziffer, Hausnummer nicht: tauschen", A = cA],
        [G = G4, B = "Telefon mit Text", Q = "ERP", F = "Telefon mit Text", V = (r) => kvs(r, {"Telefon"}), N = (h, r) => kvs(h, {"Telefon_E164"}) & " | " & bf(h, "Telefon enthält"), R = "fnTel: Nummer vor dem Text nach E.164; der Zusatz geht verloren", A = cAP],
        [G = G4, B = "Telefon mit Text", Q = "CRM", F = "Telefon mit Text", V = (r) => kvs(r, {"Telefon"}), N = (h, r) => kvs(h, {"Telefon_E164"}) & " | " & bf(h, "Telefon enthält"), R = "fnTel: Nummer vor dem Text nach E.164; der Zusatz geht verloren", A = cAP],
        [G = G4, B = "Telefon mit Text", Q = "Shop", F = "Telefon mit Text", V = (r) => kvs(r, {"phone"}), N = (h, r) => kvs(h, {"Telefon_E164"}) & " | " & bf(h, "Telefon enthält"), R = "fnTel: Nummer vor dem Text nach E.164; der Zusatz geht verloren", A = cAP],
        [G = G4, B = "E-Mail mit Transportmüll", Q = "Shop", F = "E-Mail-Transportmüll", n = 2, V = (r) => kvs(r, {"email"}), N = (h, r) => kvs(h, {"Email_norm"}), R = "fnNormEmail: mailto, Name <…>, (at), Satzzeichen, Großschrift", A = cA],
        [G = G4, B = "E-Mail mit Transportmüll", Q = "CRM", F = "E-Mail-Transportmüll", n = 1, V = (r) => kvs(r, {"E-Mail"}), N = (h, r) => kvs(h, {"Email_norm"}), R = "fnNormEmail: mailto, Name <…>, (at), Satzzeichen, Großschrift", A = cA],
        [G = G4, B = "E-Mail mit Leerzeichen", Q = "Shop", F = "E-Mail mit Leerzeichen", V = (r) => kvs(r, {"email"}), N = (h, r) => kvs(h, {"Email_norm"}), R = "fnEmails: Leerzeichen um das @ entfernen", A = cA],
        [G = G4, B = "Zwei E-Mails in einem Feld", Q = "Shop", F = "zwei E-Mails", V = (r) => kvs(r, {"email"}), N = (h, r) => kvs(h, {"Email_norm", "Email_2"}), R = "an ; , / trennen; die erste führt, die zweite bleibt für den Abgleich", A = cAP],
        [G = G4, B = "E-Mail ohne @", Q = "Shop", F = "E-Mail ohne @", V = (r) => kvs(r, {"email"}), N = (h, r) => kvs(h, {"Email_norm"}) & " | " & bf(h, "E-Mail"), R = "Syntaxprüfung; nicht reparieren, Stufe 2 der Kaskade entfällt", A = cP],
        [G = G5, B = "Bemerkung im E-Mail-Feld", Q = "Shop", F = "Bemerkung im E-Mail-Feld", V = (r) => kvs(r, {"email"}), N = (h, r) => kvs(h, {"Email_norm"}) & " | " & bf(h, "E-Mail"), R = "Syntaxprüfung; der Text ist keine Adresse", A = cP],
        [G = G5, B = "Ansprechpartner im Firmenfeld", Q = "ERP", F = "Ansprechpartner", V = (r) => kvs(r, {"Firma"}), N = (h, r) => kvs(h, {"Firma"}) & " | " & bf(h, "Zusatz"), R = "erkannt an  / , Hr., Fr.; Trennung bleibt manuell", A = cP],
        [G = G5, B = "Feldlänge 30: Name abgeschnitten", Q = "ERP", F = "Feldlänge", V = (r) => kvs(r, {"Firma"}), N = (h, r) => bf(h, "abgeschnitten"), R = "fnNameOk lässt den gemeinsamen Namensanfang gelten", A = "automatisch (Abgleich) + Prüfliste"],
        [G = G5, B = "Privatname im Firmenfeld", Q = "CRM", F = "Privatkunde", V = (r) => kvs(r, {"Firma", "Vorname", "Nachname"}), N = (h, r) => "für den Abgleich: " & t(h[Name_norm]) & " | " & bf(h, "Privatname"), R = "erstes Wort zählt als Nachname; Feldkorrektur bleibt manuell", A = "automatisch (Abgleich) + Prüfliste"],
        [G = G5, B = "Sperrvermerk im Firmenfeld", Q = "CRM", F = "Sperrvermerk im Firmenfeld", V = (r) => kvs(r, {"Firma", "Status"}), N = (h, r) => kvs(h, {"Firma", "Kontaktstatus"}), R = "Vermerk aus dem Namen lösen und als Kontaktstatus führen", A = cAP],
        [G = G5, B = "Sperrvermerk nur im Freitext", Q = "ERP", F = "Sperrvermerk nur", V = (r) => kvs(r, {"Gesperrt", "Bemerkung"}), N = (h, r) => kvs(h, {"Kontaktstatus"}) & " | " & bf(h, "Sperrvermerk"), R = "Stichwortsuche in der Bemerkung", A = cAP],
        [G = G5, B = "Betreuer als Name statt Schlüssel", Q = "CRM", F = "", W = let l = ids("CRM", "Betreuer nicht", 20) in List.FirstN(l, 1) & List.FirstN(List.Select(l, (i) => rec(CH, "AccountId", i)[Betreuer] = null), 1), V = (r) => kvs(r, {"Betreuer"}), N = (h, r) => if h[Betreuer] <> null then kvs(h, {"Betreuer"}) else bf(h, "Betreuer"), R = "Abgleich über den normalisierten Nachnamen gegen das Blatt Betreuer", A = "automatisch, Rest Prüfliste"],
        [G = G6, B = "Testkunde", Q = "ERP", F = "Testkunde", V = (r) => kvs(r, {"KdNr", "Firma"}), N = (h, r) => kvs(h, {"Flag_Test"}) & " | nicht in Kaskade und Dimension", R = "Name beginnt mit test: vor der Dublettensuche filtern", A = "verworfen"],
        [G = G6, B = "Testkunde", Q = "Shop", F = "Testkunde", V = (r) => kvs(r, {"last_name", "email"}), N = (h, r) => kvs(h, {"Flag_Test"}) & " | nicht in Kaskade und Dimension", R = "Name beginnt mit test oder E-Mail test@test.de", A = "verworfen"],
        [G = G6, B = "Testkunde", Q = "CRM", F = "Testkunde", V = (r) => kvs(r, {"Firma"}), N = (h, r) => kvs(h, {"Flag_Test"}) & " | nicht in Kaskade und Dimension", R = "Name beginnt mit test: vor der Dublettensuche filtern", A = "verworfen"],
        [G = G6, B = "Dublette im ERP", Q = "ERP", F = "Dublette im ERP", n = 2, V = (r) => kvs(r, {"KdNr", "Firma", "Anlagedatum"}), N = (h, r) => if h[Matchkey] = null then "kein Adressschlüssel: bleibt eigener Kunde" else let p = partner(EH, "KdNr", h) in if Table.IsEmpty(p) then "kein Partner mit gleichem Schlüssel und Namen" else "gleicher Adressschlüssel und Name wie KdNr " & p{0}[KdNr] & " (angelegt " & t(p{0}[Anlagedatum]) & "): ein KundeKey", R = "KUNDE_k: Adressschlüssel + Name gleich; der älteste Satz führt", A = cA],
        [G = G6, B = "Dublette im CRM", Q = "CRM", F = "", W = List.FirstN(List.Select(ids("CRM", "Dublette im CRM", 20), (i) => rec(CH, "AccountId", i)[Matchkey] <> null), 1), V = (r) => kvx(r, {"Firma", "Nachname", "Strasse", "Hausnr"}), N = (h, r) => if h[Matchkey] = null then "kein Adressschlüssel: Zuordnung nur über Schlüssel oder Namen" else let p = partner(CH, "AccountId", h) in if Table.IsEmpty(p) then "kein Partner mit gleichem Schlüssel und Namen" else "gleicher Adressschlüssel und Name wie Account " & Text.Start(p{0}[AccountId], 8) & "…: ein KundeKey", R = "CRM_k: beide Accounts erhalten über die Kaskade denselben KundeKey", A = cK],
        [G = G6, B = "Tippfehler im Namen", Q = "ERP", F = "Tippfehler", n = 2, V = (r) => kvs(r, {"Firma"}), N = (h, r) => "für den Abgleich: " & t(h[Name_norm]), R = "Stufe 1 bis 3 tragen meist; sonst Stufe 4: Ähnlichkeit ab 0,8 mit Nachregel", A = cK],
        [G = G6, B = "Fremdschlüssel mit Tippfehler", Q = "CRM", F = "Fremdschlüssel", n = 1, V = (r) => kvx(r, {"ERP_KdNr", "Firma", "Nachname"}), N = (h, r) => let e = rec(EH, "KdNr", t(r[ERP_KdNr])) in if e = null then "KdNr gibt es im ERP nicht: Stufe 1 greift nicht" else "KdNr gehört zu " & t(e[Firma] ?? e[Nachname]) & ": " & (if fnNameOk(e[Name_norm], h[Name_norm]) or (e[Matchkey] <> null and e[Matchkey] = h[Matchkey]) then "bestätigt" else "Name und Adresse passen nicht, Schlüssel verworfen"), R = "Stufe 1 gilt nur mit Bestätigung durch Name oder Adresse", A = cK],
        [G = G6, B = "Sammel-E-Mail", Q = "Shop", F = "Sammel-E-Mail", V = (r) => kvx(r, {"company", "last_name", "email"}), N = (h, r) => "E-Mail bei " & Text.From(Table.RowCount(Table.SelectRows(CH, each [Email_norm] <> null and [Email_norm] = h[Email_norm]))) & " CRM-Accounts: Zuordnung nur mit Namensbestätigung", R = "Stufe 2: nicht eindeutige E-Mail braucht den Namen; Paar auf die Prüfliste", A = "automatisch (Kaskade) + Prüfliste"],
        [G = G6, B = "Gleiche Adresse, anderer Kunde", Q = "ERP", F = "gleiche Adresse", V = (r) => kvs(r, {"Firma", "Strasse", "Ort"}), N = (h, r) => let p = List.Distinct(Table.SelectRows(ALLH, each [Matchkey] <> null and [Matchkey] = h[Matchkey] and [Name_norm] <> h[Name_norm])[Name_norm]) in "Adressschlüssel auch bei: " & (if List.IsEmpty(p) then "(niemand)" else Text.Combine(p, ", ")) & " | bleibt getrennt", R = "Stufe 3: Adresse zählt nur mit Namensbestätigung; Paar auf die Prüfliste", A = "automatisch (Kaskade) + Prüfliste"]
    },
    kurz = (id as text) => if Text.Length(id) > 12 then Text.Start(id, 8) & "…" else id,
    zeilen = (s as record) as list =>
        let
            Q = s[Q],
            W = Record.FieldOrDefault(s, "W", null),
            idl = if W <> null then W else ids(Q, s[F], Record.FieldOrDefault(s, "n", 1))
        in
            List.Transform(idl, (id) => let r = rec(RT(Q), RI(Q), id), h = rec(HT(Q), HI(Q), id) in
                [Gruppe = s[G], Fehlerbild = s[B], Quelle = Q, ID = kurz(id), Vorher = try s[V](r) otherwise "#FEHLER", Nachher = try s[N](h, r) otherwise "#FEHLER", Regel = s[R], Art = s[A]]),
    Stamm = List.Combine(List.Transform(Sp, zeilen)),
    // Bewegungsdaten und Kennzahlen
    tA = Table.Buffer(AUFTRAG), tP = Table.Buffer(AUFTRAGSPOS), tL = Table.Buffer(LIEFERUNG), tO = Table.Buffer(orders), tI = Table.Buffer(order_items),
    lid = (tab as text, f as text) as text => List.First(Table.SelectRows(Log, each [Tabelle] = tab and Text.StartsWith([Fehlertyp], f))[ID]),
    netto = (a as record, p as record) => (if p[Einheit] = "Set" then p[Menge] * 10 else p[Menge]) * p[EPreisNetto] * (if a[Waehrung] = "CHF" then pKursCHF else 1),
    bw = (b as text, q as text, id as text, v, n, r as text, a as text) => [Gruppe = G7, Fehlerbild = b, Quelle = q, ID = id, Vorher = try v() otherwise "#FEHLER", Nachher = try n() otherwise "#FEHLER", Regel = r, Art = a],
    idG = lid("AUFTRAG", "Gutschrift"), aG = rec(tA, "AuftragNr", idG), pG = Table.SelectRows(tP, each [AuftragNr] = idG),
    idD = lid("AUFTRAG", "Shop-Auftrag doppelt"), aD = rec(tA, "AuftragNr", idD),
    idW = lid("AUFTRAGSPOS", "Position ohne"), pW = rec(tP, "AuftragNr", idW),
    idV = lid("LIEFERUNG", "Versand vor"), lV = rec(tL, "LieferNr", idV), aV = rec(tA, "AuftragNr", lV[AuftragNr]),
    chf = List.Buffer(Table.SelectRows(tA, each [Waehrung] = "CHF" and [Status] <> "G")[AuftragNr]), pC = Table.SelectRows(tP, each [Einheit] = "Stk" and List.Contains(chf, [AuftragNr])){0}, aC = rec(tA, "AuftragNr", pC[AuftragNr]),
    pS = Table.SelectRows(tP, each [Einheit] = "Set"){0},
    refs = List.Buffer(List.RemoveNulls(tA[ShopRef])), oB = Table.SelectRows(tO, each [status] = "shipped" and not List.Contains(refs, [order_id])){0}, iB = rec(tI, "order_id", oB[order_id]), kB = rec(SH, "ShopID", oB[customer_id]), fB = rec(mapMwSt, "LandISO", kB[LandISO])[MwStFaktor],
    oX = Table.SelectRows(tO, each [status] = "cancelled"){0},
    aU = Table.SelectRows(tA, each [ShopRef] <> null){0},
    dP = DIM_PRODUKT{0},
    Bew = {
        bw("Gutschrift (negative Menge)", "ERP", idG, () => "Status: " & aG[Status] & " | Menge: " & Text.Combine(List.Transform(pG[Menge], t), ", "), () => "NettoEUR: " & geld(List.Sum(List.Transform(Table.ToRecords(pG), (p) => netto(aG, p)))) & " | mindert den Umsatz", "bleibt in den Fakten; keine Korrektur", "übernommen"),
        bw("Shop-Auftrag doppelt importiert", "ERP", idD, () => kvs(aD, {"AuftragNr", "ShopRef"}), () => "ShopRef steht schon bei Auftrag " & List.Min(Table.SelectRows(tA, each [ShopRef] = aD[ShopRef])[AuftragNr]) & ": spätere Zeile fällt weg", "je ShopRef nur der erste ERP-Auftrag", "verworfen"),
        bw("Position ohne Auftrag (Waise)", "ERP", idW, () => kvs(pW, {"AuftragNr", "Pos", "ArtNr"}), () => if rec(tA, "AuftragNr", idW) = null then "kein Auftragskopf: Zeile fällt weg" else "Auftragskopf vorhanden", "Inner Join von Position und Auftrag", "verworfen"),
        bw("Versand vor Auftrag", "ERP", idV, () => "Auftragsdatum: " & t(aV[Datum]) & " | Versanddatum: " & t(lV[Versanddatum]), () => "Lieferdauer: (leer) statt " & Text.From(Duration.Days(lV[Versanddatum] - aV[Datum])) & " Tage", "unplausible Dauer wird leer; der Umsatz bleibt", "automatisch"),
        bw("Währung CHF", "ERP", aC[AuftragNr], () => "EPreisNetto: " & geld(pC[EPreisNetto]) & " CHF | Menge: " & t(pC[Menge]) & " " & pC[Einheit], () => "NettoEUR: " & geld(netto(aC, pC)) & " (Kurs " & t(pKursCHF) & ")", "Parameter pKursCHF", "automatisch"),
        bw("Mengeneinheit Set", "ERP", pS[AuftragNr], () => "Menge: " & t(pS[Menge]) & " " & pS[Einheit], () => "MengeStk: " & t(pS[Menge] * 10), "ein Set sind 10 Stück", "automatisch"),
        bw("Brutto statt Netto", "Shop", iB[order_id], () => "unit_price_gross: " & geld(iB[unit_price_gross]) & " | qty: " & t(iB[qty]) & " | Land: " & t(kB[LandISO]), () => "NettoEUR: " & geld(iB[qty] * iB[unit_price_gross] / fB) & " (geteilt durch " & t(fB) & ")", "mapMwSt je Lieferland", "automatisch"),
        bw("Stornierte Bestellung", "Shop", oX[order_id], () => kvs(oX, {"status"}), () => "nicht in den Fakten", "nur shipped und paid zählen", "verworfen"),
        bw("Bestellung in Shop und ERP", "Shop", aU[ShopRef], () => "order_id: " & aU[ShopRef] & " | ERP-Auftrag: " & aU[AuftragNr], () => "Shop-Zeile fällt weg; ERP-Auftrag zählt mit Kanal Online", "Anti-Join über ShopRef", "automatisch"),
        bw("Produktschlüssel verschieden", "beide", dP[ArtNr], () => "ArtNr: " & t(dP[ArtNr]) & " | sku: " & t(dP[Shop_sku]), () => "ProduktKey: " & t(dP[ProduktKey]), "SKU = 1 + letzte vier Stellen der ArtNr", "automatisch")
    },
    Tab = Table.FromRecords(Stamm & Bew, type table [Gruppe = text, Fehlerbild = text, Quelle = text, ID = text, Vorher = text, Nachher = text, Regel = text, Art = text]),
    Nr = Table.AddIndexColumn(Tab, "Nr", 1, 1, Int64.Type),
    Sort = Table.ReorderColumns(Nr, {"Nr", "Gruppe", "Fehlerbild", "Quelle", "ID", "Vorher", "Nachher", "Art", "Regel"})
in
    Sort
